// Created: 2026-09-17

import { describe, it, expect, vi, beforeEach } from 'vitest';

// Real files under a temp dir: the lint reads the written .md back from disk.
import { mkdtempSync, mkdirSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { asciiLint } from '../../posttool/ascii-lint.js';
import type { HookInput } from '../../types.js';

// The lint only looks at paths containing "/src/" so the temp dir carries one.
const dir = mkdtempSync(join(tmpdir(), 'ascii-lint-'));
const srcDir = join(dir, 'src');
mkdirSync(srcDir, { recursive: true });

function write(name: string, content: string): string {
  const p = join(srcDir, name);
  writeFileSync(p, content, 'utf-8');
  return p;
}

function run(filePath: string) {
  const input = {
    tool_name: 'Write',
    tool_input: { file_path: filePath },
  } as unknown as HookInput;
  return asciiLint(input);
}

function findings(filePath: string): string {
  const r = run(filePath) as { systemMessage?: string };
  return r.systemMessage ?? '';
}

describe('ascii-lint single-set', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('does NOT report a default+soft mix for a render made only of section rules (v3 inventory shape)', () => {
    // The v3 inventory render (glyph 3.0, 2026-09-17) has no corners at all:
    // light rules `────`, bar meters, a `── total` line. `─` is an edge shared
    // by the default and soft sets, so before the fix every such render read
    // as "mixes glyphs from sets: default, soft" even though it uses one set.
    const p = write('inventory.md', [
      '# Inventory',
      '',
      '```',
      'MACINTOSH HD  ·  /System/Volumes/Data',
      '[▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓░░░░]',
      ' used 355 G    free 73 G    83 % full · 460 G total',
      '────────────────────────────────────────────────',
      'SAFE, pure caches; nothing lost, tools refill them',
      '────────────────────────────────────────────────',
      'Docker dangling images+build cache  ▓▓▓▓░░░  14.5 G  docker prune',
      'npm cache  ~/.npm                   ▓▓░░░░░   6.2 G  npm cache clean',
      '                                    ── 45.3 G',
      '```',
      '',
    ].join('\n'));
    expect(findings(p)).not.toMatch(/single-set/);
  });

  it('still reports a real default+soft mix when both corner styles are present', () => {
    const p = write('mixed.md', [
      '```',
      '┌──────┐',
      '│ a    │',
      '└──────┘',
      '╭──────╮',
      '│ b    │',
      '╰──────╯',
      '```',
      '',
    ].join('\n'));
    expect(findings(p)).toMatch(/single-set/);
    expect(findings(p)).toMatch(/default, soft/);
  });

  it('still reports a default+emphasis mix', () => {
    const p = write('mixed2.md', [
      '```',
      '┌──────┐',
      '│ a    │',
      '└──────┘',
      '┏━━━━━━┓',
      '┃ b    ┃',
      '┗━━━━━━┛',
      '```',
      '',
    ].join('\n'));
    expect(findings(p)).toMatch(/single-set/);
  });
});
